@DBOS.workflow(name="BdrCampaign_ada0f771")
def run_pipeline(pipeline_input: dict) -> dict:
    """End-to-end BDR outreach campaign workflow for pharma/biotech research"""

    # ─── Wave 1 ───
    # Parallel fan-out: enqueue every node in the wave, then
    # join. Each enqueued step runs as its own one-step
    # workflow; get_result() blocks durably.
    target_research_handle = _enqueue(
        target_research,
        {
            "brief": pipeline_input,
        },
    )
    taxonomy_lookup_handle = _enqueue(
        taxonomy_lookup,
        {
            "brief": pipeline_input,
        },
    )
    target_research_result = target_research_handle.get_result()
    taxonomy_lookup_result = taxonomy_lookup_handle.get_result()

    # ─── Wave 2 ───
    lead_generation_loop_result = lead_generation_loop(
        {
            "brief": pipeline_input,
            "intel": target_research_result,
            "taxonomy": taxonomy_lookup_result,
            "target_quota": pipeline_input["target_quota"],
        }
    )

    # ─── Wave 3 ───
    # ─── HITL gate: contact_review_gate ───
    # Durable receive: the workflow parks in the system database until
    # DBOS.send(workflow_id, payload, topic='contact_review_approved')
    # delivers the resume message. Survives process restarts.
    contact_review_gate_result = DBOS.recv(
        topic="contact_review_approved",
        timeout_seconds=604800,  # 7d
    )
    if contact_review_gate_result is None:
        raise TimeoutError(
            "HITL gate 'contact_review_gate' timed out after 7d waiting "
            "for signal 'contact_review_approved'"
        )

    # ─── Wave 4 ───
    hubspot_upsert_result = hubspot_upsert(
        {
            "contacts": contact_review_gate_result["approved_contacts"],
        }
    )

    # ─── Wave 5 ───
    hubspot_create_list_result = hubspot_create_list(
        {
            "campaign_name": pipeline_input["drug_brand"],
            "contacts": hubspot_upsert_result["upserted"],
        }
    )

    # ─── Wave 6 ───
    exclusion_check_dnc_result = exclusion_check_dnc(
        {
            "contacts": hubspot_upsert_result["upserted"],
        }
    )

    # ─── Wave 7 ───
    exclusion_check_recent_result = exclusion_check_recent(
        {
            "contacts": exclusion_check_dnc_result["passed"],
        }
    )

    # ─── Wave 8 ───
    exclusion_check_sequence_result = exclusion_check_sequence(
        {
            "contacts": exclusion_check_recent_result["passed"],
        }
    )

    # ─── Wave 9 ───
    # fan_out: personalize_email runs once per element of the bound
    # list, each as its own enqueued durable step.
    personalize_email_payloads = [
        {"contact": _item, "campaign_type": pipeline_input["campaign_type"], "intel": target_research_result}
        for _item in _fan_out_list(
            exclusion_check_sequence_result["passed"],
            "personalize_email",
            "exclusion_check_sequence.output.passed",
        )
    ]
    personalize_email_handles = [_enqueue(personalize_email, _p) for _p in personalize_email_payloads]
    personalize_email_result = [_h.get_result() for _h in personalize_email_handles]

    # ─── Wave 10 ───
    create_sales_template_result = create_sales_template(
        {
            "campaign_name": pipeline_input["drug_brand"],
            "personalizations": personalize_email_result,
        }
    )

    # ─── Wave 11 ───
    pre_enrollment_report_result = pre_enrollment_report(
        {
            "campaign_name": pipeline_input["drug_brand"],
            "passed_contacts": exclusion_check_sequence_result["passed"],
            "exclusions": exclusion_check_sequence_result["excluded"],
            "template_ids": create_sales_template_result["template_ids"],
        }
    )

    # ─── Wave 12 ───
    # ─── HITL gate: manual_enrollment_handoff ───
    # Durable receive: the workflow parks in the system database until
    # DBOS.send(workflow_id, payload, topic='bdr_enrollment_complete')
    # delivers the resume message. Survives process restarts.
    manual_enrollment_handoff_result = DBOS.recv(
        topic="bdr_enrollment_complete",
        timeout_seconds=1209600,  # 14d
    )
    if manual_enrollment_handoff_result is None:
        raise TimeoutError(
            "HITL gate 'manual_enrollment_handoff' timed out after 14d waiting "
            "for signal 'bdr_enrollment_complete'"
        )

    return {
        "manual_enrollment_handoff": manual_enrollment_handoff_result,
    }


